import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.Bqa2y7hU.js";const g=JSON.parse('{"title":"目录结构与打包","description":"插件在服务端的落盘目录、上传 zip 里必须有什么、插件分类规范集合与 logo 的三种来源。","frontmatter":{"title":"目录结构与打包","description":"插件在服务端的落盘目录、上传 zip 里必须有什么、插件分类规范集合与 logo 的三种来源。"},"headers":[],"relativePath":"plugin-dev/structure.md","filePath":"plugin-dev/structure.md","lastUpdated":1789230162000}'),c={name:"plugin-dev/structure.md"};function s(l,t,n,i,r,p){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="目录结构与打包" tabindex="-1">目录结构与打包 <a class="header-anchor" href="#目录结构与打包" aria-label="Permalink to &quot;目录结构与打包&quot;">​</a></h1><p>这页讲清楚插件在服务器上长什么样、你上传的压缩包会被怎么解包。读完你能自己判断「我这个包能不能传上去」「面板文件为什么没生效」。</p><h2 id="插件在服务端的运行目录" tabindex="-1">插件在服务端的运行目录 <a class="header-anchor" href="#插件在服务端的运行目录" aria-label="Permalink to &quot;插件在服务端的运行目录&quot;">​</a></h2><p>框架把每个插件放在以<strong>插件编码</strong>命名的目录下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/</span></span>
<span class="line"><span>├── echo/                  # 插件编码 = echo</span></span>
<span class="line"><span>│   └── echo.so            # 插件本体（保留你上传时的文件名）</span></span>
<span class="line"><span>├── panel_demo/</span></span>
<span class="line"><span>│   ├── panel_demo.so      # 插件本体</span></span>
<span class="line"><span>│   └── web/               # Web 面板静态资源（只有带面板的插件才有）</span></span>
<span class="line"><span>│       ├── index.html     # 面板入口，名字由元数据的 web_entry 指定</span></span>
<span class="line"><span>│       └── assets/…       # 面板自带的 CSS / JS / 图片</span></span>
<span class="line"><span>└── .upload/               # 上传中转目录（读取元数据用，无需关心）</span></span></code></pre></div><p>要点：</p><ul><li>目录名固定为<strong>插件编码</strong>（<code>meta</code> 里的 <code>code</code>），不是文件名；</li><li>插件本体的文件名沿用你上传时的名字（会被净化掉路径分隔符）；</li><li><code>web/</code> 目录<strong>可选</strong>：插件可以只有设置项（走控制台的 schema 配置抽屉），完全不需要面板；</li><li>面板是<strong>相对路径</strong>加载的，<code>web_entry</code> 写 <code>index.html</code> 就指 <code>plugins/&lt;code&gt;/web/index.html</code>。</li></ul><h2 id="上传的-zip-里必须有什么" tabindex="-1">上传的 zip 里必须有什么 <a class="header-anchor" href="#上传的-zip-里必须有什么" aria-label="Permalink to &quot;上传的 zip 里必须有什么&quot;">​</a></h2><p>管理后台上传时接受 <code>.so</code>、<code>.dll</code> 或 <code>.zip</code>。zip 的解包规则很简单：</p><table tabindex="0"><thead><tr><th>zip 内的条目</th><th>是否采用</th><th>说明</th></tr></thead><tbody><tr><td>任意层级的 <code>.so</code> / <code>.dll</code></td><td>取<strong>第一个</strong></td><td>插件本体；同名的多个只会用第一个</td></tr><tr><td>以 <code>web/</code> 开头的条目</td><td>全部采用</td><td>落盘到 <code>plugins/&lt;code&gt;/web/</code> 下（自动剥掉 <code>web/</code> 前缀）</td></tr><tr><td>其它文件（<code>README.md</code>、源码、<code>manifest.json</code>…）</td><td>忽略</td><td>不会落盘，也不会报错</td></tr></tbody></table><p>同时支持<strong>直接上传裸 <code>.so</code></strong>（不打 zip）：此时视为只有插件本体，没有面板资源。</p><div class="tip custom-block"><p class="custom-block-title">打包约定</p><ul><li>一个包 = 一个插件；</li><li>面板入口建议就叫 <code>web/index.html</code>，这是最常见的写法；</li><li>面板入口的默认值：如果 zip 里带了 <code>web/</code> 而元数据没声明 <code>web_entry</code>，框架会按 <code>index.html</code> 处理。</li></ul></div><p>面板目录内<strong>单个文件不能超过 8 MB</strong>（加载时限制），面板资源请保持精简。</p><h2 id="插件分类规范" tabindex="-1">插件分类规范 <a class="header-anchor" href="#插件分类规范" aria-label="Permalink to &quot;插件分类规范&quot;">​</a></h2><p>插件的 <code>CATEGORY</code>（注册宏第 5 个参数）决定它在插件市场里归到哪个标签页。<strong>只有下面 8 个是规范集合</strong>：</p><table tabindex="0"><thead><tr><th>分类</th><th>适合放什么</th></tr></thead><tbody><tr><td><code>tool</code></td><td>工具类：查询、翻译、提醒、签到统计</td></tr><tr><td><code>fun</code></td><td>娱乐类：表情包、语录、随机图</td></tr><tr><td><code>game</code></td><td>游戏类：群内小游戏、抽卡</td></tr><tr><td><code>ai</code></td><td>AI 类：对话、绘图、语音合成</td></tr><tr><td><code>social</code></td><td>社交类：欢迎、名片、群互动</td></tr><tr><td><code>media</code></td><td>媒体类：点歌、视频解析、图片处理</td></tr><tr><td><code>admin</code></td><td>管理类：违禁词、链接拦截、禁言踢人</td></tr><tr><td><code>other</code></td><td>兜底分类</td></tr></tbody></table><p><strong>不在集合内的分类会被自动归到 <code>other</code></strong>（上传时会写入一条提示日志）。所以 <code>CATEGORY</code> 直接填上面表里的英文单词，别填中文或自造标签。</p><h2 id="插件-logo-的三种来源" tabindex="-1">插件 logo 的三种来源 <a class="header-anchor" href="#插件-logo-的三种来源" aria-label="Permalink to &quot;插件 logo 的三种来源&quot;">​</a></h2><p>框架读取 logo 的顺序是<strong>从优先到兜底</strong>：</p><table tabindex="0"><thead><tr><th>优先级</th><th>来源</th><th>做法</th></tr></thead><tbody><tr><td>1（最高）</td><td>内嵌字节</td><td>导出 <code>bot_plugin_logo_data()</code> / <code>bot_plugin_logo_size()</code>，用 <code>BOT_PLUGIN_LOGO_EMBED(kLogo, sizeof(kLogo) - 1)</code> 一行搞定；字节随动态库一起分发，<strong>无需外链、不怕图床挂</strong></td></tr><tr><td>2</td><td>网络 URL</td><td>元数据 <code>LOGO</code> 填 <code>https://…</code>，市场卡片直接外链显示</td></tr><tr><td>3</td><td>本地文件</td><td>元数据 <code>LOGO</code> 填相对 <code>.so</code> 目录的路径（如 <code>logo.png</code>）；上传时框架会读取文件字节入库</td></tr></tbody></table><details class="details custom-block"><summary>说明</summary><ul><li>同时导出 <code>data</code> 与 <code>size</code> 且 <code>size &gt; 0</code> 时，内嵌字节优先于元数据里的 <code>LOGO</code> 字符串；</li><li>本地文件路径若是相对路径，基准是插件动态库所在目录；绝对路径也能用，但不利于分发，不推荐；</li><li>支持的格式：PNG / JPG / SVG / ICO 等原始字节。</li></ul></details><p><strong>推荐尺寸</strong>：市场卡片与详情页都按<strong>正方形</strong>展示 logo，建议提供正方形图（例如 128×128 或 256×256 的 PNG，或矢量 SVG）。用现成的框架示例写法最省事——<code>echo</code> 与 <code>intercept</code> 都用的是一个 64×64 的内嵌 SVG。</p><h2 id="重新上传同一编码的插件" tabindex="-1">重新上传同一编码的插件 <a class="header-anchor" href="#重新上传同一编码的插件" aria-label="Permalink to &quot;重新上传同一编码的插件&quot;">​</a></h2><ul><li>允许：会覆盖同名插件的记录与文件，<strong>上传即热加载</strong>，已经装了它的机器人立刻用上新版本；</li><li><code>web/</code> 目录内的文件会<strong>整体替换</strong>（上传带 <code>web/</code> 的包时先清空旧目录再写入），别指望残留旧文件；</li><li>版本号（<code>VERSION</code>）只是展示与识别用，不影响覆盖逻辑。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/plugin-dev/abi">ABI 与兼容规则</a>：换版本后什么时候必须重新编译</li><li><a href="/RuaBot.Doc/plugin-dev/webui">插件 Web 面板</a>：<code>web/</code> 目录怎么写、入口怎么声明</li><li><a href="/RuaBot.Doc/plugin-dev/publish">云编译与上架</a>：产物 zip 长什么样、怎么上架</li></ul>`,26)])])}const u=e(c,[["render",s]]);export{g as __pageData,u as default};
